      if(turn===1){q.variant='story';q.context=q.op==='add'?q.a+' taş vardı. '+q.b+' taş daha geldi. Şimdi kaç taş var?':q.op==='sub'?q.a+' tahtanın '+q.b+' tanesi kullanıldı. Kaç tahta kaldı?':q.op==='mul'?q.a+' sıranın her birinde '+q.b+' fidan var. Toplam kaç fidan?':q.a+' elmayı '+q.b+' sepete eşit paylaştır. Her sepette kaç elma olur?';}
