      const p=enrich(createPlayer(s.name,grade,[...new Set(s.ops)],num(s.skin,3)));p.route=s.route;p.practice=s.practice;for(const k of ['wood','stone','food','diamond','lava','answered'])p[k]=num(s[k]);p.hp=num(s.hp,5);p.hero=rules.normalizeHero(s.hero,p.answered);if(typeof s.worldId==='string'&&/^[a-zA-Z0-9-]{6,80}$/.test(s.worldId))p.worldId=s.worldId;for(const k of ['built','diamondTaken','lavaTaken','portalFrame','armor','portalActive','netherVisited','netherReturned','won','freeplay','pet'])p[k]=bool(s[k]);p.endCharge=num(s.endCharge,5);p.dragonHits=num(s.dragonHits,5);p.calm={bridge:bool(s.calm?.bridge),rescued:num(s.calm?.rescued,3),planted:num(s.calm?.planted,3),light:num(s.calm?.light,5)};
      const depleted=(dest,src)=>{if(!Array.isArray(src)||src.length!==dest.length)fail();dest.forEach((o,i)=>o.depleted=bool(src[i]?.depleted));};depleted(p.objects,s.objects);depleted(p.blazes,s.blazes);depleted(p.endermen,s.endermen);
      if(!Array.isArray(s.regions)||s.regions.length>500)fail();p.regions=s.regions.map((r,i)=>{const fresh=createIsland(i+1);depleted(fresh.objects,r.objects);if(!Array.isArray(r.buildings)||r.buildings.length>64)fail();fresh.buildings=r.buildings.map(o=>{if(!buildingPlans[o.kind])fail();const x=num(o.x,13),y=num(o.y,13);if(x<1||y<1)fail();return{kind:o.kind,x,y,w:2,d:2,type:'structure',art:'structure',depleted:false};});for(let j=0;j<fresh.buildings.length;j++){const item=fresh.buildings[j];if(overlap(item,{x:7,y:0,w:1,d:16})||overlap(item,node('returnHome',7,13,2,1))||fresh.objects.some(o=>!o.depleted&&overlap(item,o))||fresh.buildings.slice(0,j).some(o=>overlap(item,o)))fail();}return fresh;});
      if(!['overworld','frontier','cave','nether','end'].includes(s.zone))fail();p.zone=s.zone;p.region=num(s.region,p.regions.length);if((p.zone==='frontier'&&p.region<1)||(p.zone!=='frontier'&&p.region!==0)||(p.route==='calm'&&!['overworld','frontier'].includes(p.zone)))fail();p.x=num(s.x,15);p.y=num(s.y,15);if(p.route==='calm')p.hp=5;
      if(!s.day||!/^\d{4}-\d{1,2}-\d{1,2}$/.test(s.day.date)||![10,15,20,30].includes(s.day.limit)||!Number.isFinite(s.day.usedMs)||s.day.usedMs<0||s.day.usedMs>86400000)fail();p.day={date:s.day.date,limit:s.day.limit,usedMs:s.day.usedMs};p.manualPaused=false;
