    setInterval(()=>{if(!root.isConnected)return;const now=performance.now(),delta=Math.min(1500,Math.max(0,now-lastClock));lastClock=now;const oldDate=player.day.date,wasUp=timeUp();if(!externalLocked&&!document.hidden&&activeView!=='players'&&!player.manualPaused&&!wasUp&&!finished()&&now-lastInput<60000)dayState().usedMs+=delta;let changed=false;for(const p of players)for(const project of Object.values(p.projects)){if(project.status==='building'&&Date.now()>=project.due){project.status='done';if(p===player){changed=true;sound('project');}}}updateClock();if(activeView==='growth')updateGrowth();if(changed||oldDate!==player.day.date||wasUp!==timeUp())render();if(++saveTick%15===0)notifyState();},1000);
    function avatarElement(index){const s=skins[index],span=document.createElement('span');span.className='mv-avatar';span.setAttribute('aria-hidden','true');span.style.setProperty('--avatar-color',s.shirt);span.style.setProperty('--skin-color',s.skin);span.style.setProperty('--hair-color',s.hair);return span;}
